begin;
create or replace function public.community_api(p_route text,p_method text default 'GET',p_body jsonb default '{}',p_query jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare uid uuid:=auth.uid(); parts text[]:=string_to_array(p_route,'/');target uuid;pid uuid:=private.community_project();a text:=p_body->>'action';out jsonb;id uuid;f public.friendships;r public.rides;q public.ride_requests;l public.exchange_listings;h public.home_listings;c public.exchange_conversations;status text;mid text;amt bigint;blocked record;
begin
 if uid is null then raise exception 'Sign in to MD One';end if;
 if p_method not in ('GET','POST','PATCH') then raise exception 'Method unavailable';end if;
 if p_route='community' and p_method='GET' then
 return jsonb_build_object('eligible',private.active_resident(uid),'owner',private.staff_role(array['platform']),'user',jsonb_build_object('id',uid,'name',(select display_name from public.profiles where profiles.id=uid)),'projects',(select coalesce(jsonb_agg(to_jsonb(p) order by p.name),'[]') from public.projects p),'services',jsonb_build_object('carpool',private.active_resident(uid)),'rides',public.community_api('rides'),'social',jsonb_build_object('profile',private.community_profile(uid),'people',coalesce((select jsonb_agg(private.community_profile(p.user_id)) from (select user_id from public.social_profiles where user_id<>uid and private.can_discover_profile(user_id) order by updated_at desc limit 60) p),'[]'),'feed',coalesce((select jsonb_agg(private.community_post(p) order by p.created_at desc) from (select * from public.posts where private.post_is_visible(posts.id) order by created_at desc limit 30) p),'[]'),'connections',coalesce((select jsonb_agg(to_jsonb(f)||jsonb_build_object('other',case when private.can_discover_profile(case when f.sender_id=uid then f.recipient_id else f.sender_id end) then private.community_profile(case when f.sender_id=uid then f.recipient_id else f.sender_id end) else jsonb_build_object('id',case when f.sender_id=uid then f.recipient_id else f.sender_id end,'name','Private resident','locked',true) end)) from public.friendships f where uid in(f.sender_id,f.recipient_id) and f.status in ('pending','accepted') and not private.are_blocked(f.sender_id,f.recipient_id)),'[]')));
 end if;
 if parts[1]='profiles' and p_method='GET' then target:=parts[2]::uuid;return private.community_profile(target)||jsonb_build_object('posts',coalesce((select jsonb_agg(private.community_post(p) order by p.created_at desc) from (select * from public.posts where user_id=target and private.post_is_visible(posts.id) order by created_at desc limit 30) p),'[]'));end if;
 if p_route='my-profile' and p_method='POST' then
 mid:=coalesce(p_body->>'avatar','');if not private.own_media(mid) then raise exception 'Invalid profile photo';end if;
 update public.social_profiles set bio=coalesce(p_body->>'bio',''),occupation=coalesce(p_body->>'occupation',''),contact=coalesce(p_body->>'contact',''),contact_visibility=p_body->>'contactVisibility',locked=coalesce((p_body->>'locked')::boolean,true),discoverable=coalesce((p_body->>'discoverable')::boolean,false),network_visible=coalesce((p_body->>'networkVisible')::boolean,false),avatar_key=nullif(mid,''),updated_at=now() where user_id=uid;
 if p_body ? 'name' then if length(trim(p_body->>'name')) not between 1 and 80 then raise exception 'Enter a name under 80 characters';end if;update public.profiles set display_name=trim(p_body->>'name') where profiles.id=uid;end if;
 return jsonb_build_object('ok',true);end if;
 if p_route='my-project' and p_method='GET' then return jsonb_build_object('projects',coalesce((select jsonb_agg(jsonb_build_object('project_id',p.id,'project',p.name,'flat_id',f.id,'label',f.label)) from public.memberships m join public.flats f on f.id=m.flat_id join public.projects p on p.id=f.project_id where m.user_id=uid and not f.is_test and m.status='approved' and m.move_in<=now() and (m.move_out is null or m.move_out>now())),'[]'),'invitations','[]'::jsonb);end if;
 -- A non-resident platform founder can browse these empty/private projections;
 -- resident actions remain tied to approved real residences, never staff powers.
 if parts[1]='rides' and p_method='GET' then
 if not private.active_resident(uid) then return '[]';end if;
 return coalesce((select jsonb_agg(card order by departure) from (select r.departure,jsonb_build_object('id',r.id,'user_id',r.driver_id,'driver',pr.display_name,'project',pj.name,'pickup',r.pickup_area,'destination',r.destination_area,'departure',r.departure,'seats',r.seats,'status',r.status,'ownContact',coalesce((select phone from private.ride_contacts where ride_id=r.id and user_id=uid),''),'contact',case when exists(select 1 from public.ride_requests where ride_id=r.id and user_id=uid and status='accepted') then coalesce((select phone from private.ride_contacts where ride_id=r.id and user_id=r.driver_id),'') else '' end,'requests',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'user_id',q.user_id,'name',qp.display_name,'status',q.status,'contact',case when r.driver_id=uid and q.status='accepted' then coalesce((select phone from private.ride_contacts where ride_id=r.id and user_id=q.user_id),'') else '' end)) from public.ride_requests q join public.profiles qp on qp.id=q.user_id where q.ride_id=r.id and (r.driver_id=uid or q.user_id=uid) and private.active_resident(q.user_id) and not private.are_blocked(r.driver_id,q.user_id)),'[]')) card from public.rides r join public.profiles pr on pr.id=r.driver_id join public.projects pj on pj.id=r.project_id where r.status='open' and r.departure>now() and private.project_member(r.driver_id,r.project_id) and not private.are_blocked(uid,r.driver_id) order by r.departure limit 150) v),'[]');end if;
 if parts[1]='exchange' and p_method='GET' then
 if p_route='exchange' then
 return jsonb_build_object('listings',coalesce((select jsonb_agg(private.exchange_card(l) order by l.created_at desc) from (select * from public.exchange_listings x where private.exchange_visible(x.id) and (coalesce(p_query->>'search','')='' or x.title ilike '%'||(p_query->>'search')||'%' or x.description ilike '%'||(p_query->>'search')||'%') and (coalesce(p_query->>'category','')='' or x.category=p_query->>'category') and (coalesce(p_query->>'condition','')='' or x.condition=p_query->>'condition') and (coalesce(p_query->>'type','')='' or x.type=p_query->>'type') and (coalesce(p_query->>'project','')='' or x.project_id::text=p_query->>'project') and (coalesce(p_query->>'maxPrice','')='' or x.price<=(p_query->>'maxPrice')::bigint) and (coalesce(p_query->>'saved','')='' or exists(select 1 from public.exchange_saves where listing_id=x.id and user_id=uid)) order by created_at desc,id limit 24 offset greatest(0,least(coalesce((p_query->>'offset')::integer,0),10000))) l),'[]'),'nextOffset',case when (select count(*) from public.exchange_listings x where private.exchange_visible(x.id))>coalesce((p_query->>'offset')::integer,0)+24 then coalesce((p_query->>'offset')::integer,0)+24 else null end);end if;
 if parts[2]='conversations' then
 if parts[3] is null then return coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('title',l.title)) from public.exchange_conversations c join public.exchange_listings l on l.id=c.listing_id where private.exchange_participant(c.id)),'[]');end if;
 target:=parts[3]::uuid;if not private.exchange_participant(target) then raise exception 'Conversation unavailable';end if;return coalesce((select jsonb_agg(to_jsonb(m)||jsonb_build_object('created',m.created_at) order by m.created_at) from (select * from public.exchange_messages where conversation_id=target order by created_at desc limit 200) m),'[]');end if;
 target:=parts[2]::uuid;if not private.exchange_visible(target) then raise exception 'Listing unavailable';end if;select * into l from public.exchange_listings where exchange_listings.id=target;return private.exchange_card(l);end if;
 if parts[1]='homes' and p_method='GET' then
 if parts[2] is not null then target:=parts[2]::uuid;if not private.home_visible(target) then raise exception 'Home unavailable';end if;select * into h from public.home_listings where home_listings.id=target;return private.home_card(h);end if;
 return jsonb_build_object('listings',coalesce((select jsonb_agg(private.home_card(l) order by l.created_at desc) from (select h.* from public.home_listings h join public.flats f on f.id=h.flat_id where private.home_visible(h.id) and h.status='available' and h.expires>now() and (coalesce(p_query->>'purpose','')='' or h.purpose=p_query->>'purpose') and (coalesce(p_query->>'project','')='' or f.project_id::text=p_query->>'project') and (coalesce(p_query->>'bhk','')='' or h.bhk::text=p_query->>'bhk') and (coalesce(p_query->>'search','')='' or h.title ilike '%'||(p_query->>'search')||'%') order by h.created_at desc limit 40) l),'[]'),'mine',coalesce((select jsonb_agg(private.home_card(h)) from public.home_listings h where h.user_id=uid and private.home_visible(h.id)),'[]'),'ownedFlats',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'label',f.label,'project',p.name)) from public.ownership o join public.flats f on f.id=o.flat_id join public.projects p on p.id=f.project_id where o.user_id=uid and not f.is_test),'[]'),'projects',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from public.projects p),'next',null);end if;
 if parts[1]='homes' and p_method='POST' and parts[2] is null then
 if not exists(select 1 from public.ownership o join public.flats f on f.id=o.flat_id where o.user_id=uid and o.flat_id=(p_body->>'flatId')::uuid and not f.is_test) then raise exception 'Verified flat ownership required';end if;
 perform private.check_photos(coalesce(p_body->'photos','[]'),8);
 if length(coalesce(p_body->>'key','')) not between 10 and 100 then raise exception 'Missing request key';end if;
 select home_listings.id into id from public.home_listings where user_id=uid and request_key=p_body->>'key';if found then return jsonb_build_object('id',id);end if;
 insert into public.home_listings(user_id,flat_id,purpose,title,description,bhk,area,floor,furnishing,parking,available,price,deposit,photos,request_key) values(uid,(p_body->>'flatId')::uuid,p_body->>'purpose',trim(p_body->>'title'),trim(p_body->>'description'),(p_body->>'bhk')::integer,(p_body->>'area')::integer,(p_body->>'floor')::integer,left(p_body->>'furnishing',60),(p_body->>'parking')::integer,(p_body->>'available')::date,(p_body->>'price')::bigint,(p_body->>'deposit')::bigint,coalesce(p_body->'photos','[]'),p_body->>'key') returning home_listings.id into id;return jsonb_build_object('id',id);end if;
 if parts[1]='homes' and parts[3]='action' and p_method='POST' then
 target:=parts[2]::uuid;select * into h from public.home_listings where home_listings.id=target for update;if not found or not private.home_visible(target) then raise exception 'Home unavailable';end if;
 if a in ('status','renew') then
 if h.user_id<>uid then raise exception 'Owner only';end if;
 if a='status' then if p_body->>'status' not in ('rented','sold','withdrawn') then raise exception 'Invalid status';end if;update public.home_listings set status=p_body->>'status' where home_listings.id=target;else update public.home_listings set status='available',expires=now()+interval '30 days' where home_listings.id=target;end if;
 elsif a='interest' then if uid=h.user_id or not private.active_resident(uid) or h.status<>'available' or h.expires<=now() then raise exception 'Home unavailable';end if;insert into public.home_interests(listing_id,user_id) values(target,uid) on conflict(listing_id,user_id) do update set status=case when home_interests.status in ('withdrawn','declined') then 'pending' else home_interests.status end;
 elsif a='withdraw' then update public.home_interests set status='withdrawn' where listing_id=target and user_id=uid;delete from private.home_contacts where listing_id=target and user_id=uid;
 elsif a in ('accept','decline') then if h.user_id<>uid or h.status<>'available' or h.expires<=now() then raise exception 'Owner only on available home';end if;update public.home_interests hi set status=case when a='accept' then 'accepted' else 'declined' end where hi.id=(p_body->>'requestId')::uuid and hi.listing_id=target and hi.status='pending' and private.active_resident(hi.user_id) and not private.are_blocked(uid,hi.user_id);if not found then raise exception 'Request unavailable';end if;
 elsif a='contact' then if coalesce(p_body->>'contact','')='' then delete from private.home_contacts where listing_id=target and user_id=uid;else if h.status<>'available' or h.expires<=now() or (uid<>h.user_id and not exists(select 1 from public.home_interests where listing_id=target and user_id=uid and status='accepted')) or coalesce((p_body->>'consent')::boolean,false)=false or (p_body->>'contact') !~ '^\+?[0-9]{10,15}$' then raise exception 'Accepted interest and phone consent required';end if;insert into private.home_contacts values(target,uid,p_body->>'contact') on conflict(listing_id,user_id) do update set phone=excluded.phone;end if;
 else raise exception 'Unknown home action';end if;return jsonb_build_object('ok',true);end if;
 -- All remaining actions require a real, active resident. Ownership alone only lists homes.
 if not private.active_resident(uid) then raise exception 'An approved residence is required for this action';end if;
 if parts[1]='friends' and p_method='POST' then
 target:=parts[2]::uuid;if target=uid or not private.active_resident(target) or private.are_blocked(uid,target) then raise exception 'Connection unavailable';end if;
 perform pg_advisory_xact_lock(hashtextextended(least(uid,target)::text||greatest(uid,target)::text,0));
 select * into f from public.friendships where least(sender_id,recipient_id)=least(uid,target) and greatest(sender_id,recipient_id)=greatest(uid,target) for update;
 if a='request' then if not private.can_discover_profile(target) then raise exception 'Profile unavailable';end if;if f.id is null then insert into public.friendships(sender_id,recipient_id) values(uid,target);elsif f.status in ('declined','cancelled') then update public.friendships set sender_id=uid,recipient_id=target,status='pending',updated_at=now() where friendships.id=f.id;end if;
 elsif a in ('accept','decline') then if f.recipient_id<>uid or f.status<>'pending' then raise exception 'Incoming request required';end if;update public.friendships set status=case when a='accept' then 'accepted' else 'declined' end,updated_at=now() where friendships.id=f.id;
 elsif a in ('cancel','remove') then if f.id is null or a='cancel' and f.sender_id<>uid then raise exception 'Connection unavailable';end if;update public.friendships set status='cancelled',updated_at=now() where friendships.id=f.id;
 else raise exception 'Unknown connection action';end if;return jsonb_build_object('ok',true);end if;
 if parts[1]='blocks' and p_method='POST' then target:=parts[2]::uuid;if target=uid then raise exception 'Cannot block yourself';end if;
 for blocked in select rr.id,rr.ride_id from public.ride_requests rr join public.rides rd on rd.id=rr.ride_id where (rd.driver_id=uid and rr.user_id=target or rd.driver_id=target and rr.user_id=uid) and rr.status in ('pending','accepted') order by rd.id for update of rd,rr loop
 if (select rr.status from public.ride_requests rr where rr.id=blocked.id)='accepted' then update public.rides set seats=seats+1 where rides.id=blocked.ride_id and rides.status='open';end if;
 update public.ride_requests set status='cancelled' where ride_requests.id=blocked.id;
 delete from private.ride_contacts where ride_id=blocked.ride_id and user_id in(uid,target);
 end loop;
 delete from private.home_contacts hc using public.home_listings hl where hc.listing_id=hl.id and (hl.user_id=uid and hc.user_id=target or hl.user_id=target and hc.user_id=uid);
 insert into public.blocks(user_id,target_id) values(uid,target) on conflict do nothing;update public.friendships set status='cancelled' where uid in(sender_id,recipient_id) and target in(sender_id,recipient_id);return jsonb_build_object('ok',true);end if;
 if p_route='social-posts' and p_method='POST' then
 if p_body->>'visibility'='network' and not exists(select 1 from public.social_profiles where user_id=uid and network_visible) then raise exception 'Enable network visibility in your profile first';end if;
 mid:=coalesce(p_body->>'image','');if not private.own_media(mid) then raise exception 'Invalid post image';end if;
 insert into public.posts(project_id,user_id,body,visibility,image_key) values(pid,uid,trim(p_body->>'body'),p_body->>'visibility',nullif(mid,'')) returning posts.id into id;return jsonb_build_object('id',id);end if;
 if parts[1]='social-posts' and p_method='POST' then target:=parts[2]::uuid;
 if a='delete' then update public.posts set status='hidden' where posts.id=target and user_id=uid;if not found then raise exception 'Post unavailable';end if;
 else if not private.post_is_visible(target) then raise exception 'Post unavailable';end if;
 if a='like' then perform pg_advisory_xact_lock(hashtextextended(uid::text||target::text,0));delete from public.post_likes where post_id=target and user_id=uid;if not found then insert into public.post_likes values(target,uid);end if;
 elsif a='comment' then insert into public.post_comments(post_id,user_id,body) values(target,uid,trim(p_body->>'body'));else raise exception 'Unknown post action';end if;end if;return jsonb_build_object('ok',true);end if;
 if p_route='rides' and p_method='POST' then
 if length(trim(p_body->>'pickup')) not between 2 and 100 or length(trim(p_body->>'destination')) not between 2 and 100 or (p_body->>'departure')::timestamptz<=now() or (p_body->>'departure')::timestamptz>now()+interval '90 days' or (p_body->>'seats')::integer not between 1 and 6 then raise exception 'Check route, future departure and 1–6 seats';end if;
 if (select count(*) from public.rides where driver_id=uid and status='open' and departure>now())>=20 then raise exception 'Maximum 20 open journeys';end if;
 insert into public.rides(driver_id,project_id,pickup_area,destination_area,departure,seats) values(uid,pid,trim(p_body->>'pickup'),trim(p_body->>'destination'),(p_body->>'departure')::timestamptz,(p_body->>'seats')::integer) returning rides.id into id;return jsonb_build_object('id',id);end if;
 if parts[1]='rides' and p_method='PATCH' then
 target:=parts[2]::uuid;select * into r from public.rides where rides.id=target for update;
 if not found or r.status<>'open' or r.departure<=now() or not private.project_member(r.driver_id,r.project_id) or private.are_blocked(uid,r.driver_id) then raise exception 'Journey unavailable';end if;
 if a='request' then if r.driver_id=uid or r.seats<1 then raise exception 'Journey unavailable';end if;insert into public.ride_requests(ride_id,user_id) values(target,uid) on conflict(ride_id,user_id) do update set status=case when ride_requests.status in ('cancelled','rejected') then 'pending' else ride_requests.status end;
 elsif a in ('accept','reject') then
 if r.driver_id<>uid then raise exception 'Journey owner only';end if;
 select * into q from public.ride_requests where ride_requests.id=(p_body->>'requestId')::uuid and ride_id=target for update;
 if not found or not private.active_resident(q.user_id) or private.are_blocked(uid,q.user_id) then raise exception 'Request unavailable';end if;
 if a='accept' and q.status='accepted' then return jsonb_build_object('ok',true);end if;
 if q.status<>'pending' then raise exception 'Pending request required';end if;
 if a='accept' then if r.seats<1 then raise exception 'No seats remaining';end if;update public.rides set seats=seats-1 where rides.id=target;end if;
 update public.ride_requests set status=case when a='accept' then 'accepted' else 'rejected' end where ride_requests.id=q.id;
 elsif a='withdraw' then select * into q from public.ride_requests where ride_id=target and user_id=uid for update;if q.status='accepted' then update public.rides set seats=seats+1 where rides.id=target;end if;update public.ride_requests set status='cancelled' where ride_id=target and user_id=uid;delete from private.ride_contacts where ride_id=target and user_id=uid;
 elsif a='cancel' then if r.driver_id<>uid then raise exception 'Journey owner only';end if;update public.rides set status='cancelled' where rides.id=target;update public.ride_requests set status='cancelled' where ride_id=target;delete from private.ride_contacts where ride_id=target;
 elsif a='share_contact' then
 if uid<>r.driver_id and not exists(select 1 from public.ride_requests where ride_id=target and user_id=uid and status='accepted') then raise exception 'Accepted connection required';end if;
 if coalesce(p_body->>'contact','')='' then delete from private.ride_contacts where ride_id=target and user_id=uid;else if (p_body->>'contact') !~ '^\+?[0-9]{10,15}$' then raise exception 'Enter a valid phone number';end if;insert into private.ride_contacts values(target,uid,p_body->>'contact') on conflict(ride_id,user_id) do update set phone=excluded.phone;end if;
 elsif a='block' then return public.community_api('blocks/'||(p_body->>'targetId'),'POST','{}');
 elsif a='report' then if length(trim(p_body->>'reason')) not between 1 and 500 then raise exception 'Enter a report reason';end if;insert into private.community_reports(user_id,kind,target_id,reason) values(uid,'ride',target,trim(p_body->>'reason'));
 else raise exception 'Unknown journey action';end if;return jsonb_build_object('ok',true);end if;
 if parts[1]='exchange' and p_method='POST' then
 if parts[2]='reports' then if p_body->>'kind' not in ('listing','message') or length(trim(p_body->>'reason')) not between 1 and 500 then raise exception 'Invalid report';end if;target:=(p_body->>'targetId')::uuid;if p_body->>'kind'='listing' and not private.exchange_visible(target) or p_body->>'kind'='message' and not exists(select 1 from public.exchange_messages where exchange_messages.id=target and private.exchange_participant(conversation_id)) then raise exception 'Report target unavailable';end if;insert into private.exchange_reports(user_id,kind,target_id,reason) values(uid,p_body->>'kind',target,trim(p_body->>'reason'));return jsonb_build_object('ok',true);end if;
 if parts[2]='conversations' then target:=parts[3]::uuid;if not private.exchange_participant(target) then raise exception 'Conversation unavailable';end if;
 if length(coalesce(p_body->>'key','')) not between 10 and 100 then raise exception 'Missing request key';end if;
 insert into public.exchange_messages(conversation_id,user_id,body,request_key) values(target,uid,trim(p_body->>'body'),p_body->>'key') on conflict(user_id,request_key) do nothing;return jsonb_build_object('ok',true);end if;
 if parts[3]='action' then
 target:=parts[2]::uuid;if not private.exchange_visible(target) then raise exception 'Listing unavailable';end if;select * into l from public.exchange_listings where exchange_listings.id=target for update;
 if a='save' then insert into public.exchange_saves values(uid,target) on conflict do nothing;
 elsif a='unsave' then delete from public.exchange_saves where user_id=uid and listing_id=target;
 elsif a='enquire' then if l.user_id=uid or l.status not in ('active','reserved') or l.expires<=now() then raise exception 'Listing not open for enquiries';end if;insert into public.exchange_conversations(listing_id,buyer_id) values(target,uid) on conflict(listing_id,buyer_id) do nothing;select * into c from public.exchange_conversations where listing_id=target and buyer_id=uid;return to_jsonb(c)||jsonb_build_object('title',l.title);
 else raise exception 'Unknown listing action';end if;return jsonb_build_object('ok',true);end if;
 pid:=(p_body->>'projectId')::uuid;if not private.active_project(pid) then raise exception 'Approved project membership required';end if;
 perform private.check_photos(coalesce(p_body->'photos','[]'),5);
 if p_body->>'category' not in ('Furniture','Electronics','Appliances','Books','Children’s items','Cycles','Fitness','Home and garden','Other') or p_body->>'condition' not in ('New','Like new','Good','Fair') or length(coalesce(p_body->>'exchangePreference',''))>500 or length(coalesce(p_body->>'key','')) not between 10 and 100 then raise exception 'Check category, condition and request key';end if;
 amt:=(p_body->>'price')::bigint;if amt<0 or amt>1000000000 then raise exception 'Invalid price';end if;
 if parts[2] is null then
 select exchange_listings.id into id from public.exchange_listings where user_id=uid and request_key=p_body->>'key';if found then return jsonb_build_object('id',id);end if;
 insert into public.exchange_listings(project_id,user_id,title,description,category,condition,type,price,audience,status,photo_keys,exchange_preference,expires,request_key) values(pid,uid,trim(p_body->>'title'),trim(p_body->>'description'),p_body->>'category',p_body->>'condition',p_body->>'type',case when p_body->>'type'='free' then 0 else amt end,p_body->>'audience',p_body->>'status',coalesce(p_body->'photos','[]'),coalesce(p_body->>'exchangePreference',''),now()+interval '30 days',p_body->>'key') returning exchange_listings.id into id;
 else target:=parts[2]::uuid;update public.exchange_listings set title=trim(p_body->>'title'),description=trim(p_body->>'description'),category=p_body->>'category',condition=p_body->>'condition',type=p_body->>'type',price=case when p_body->>'type'='free' then 0 else amt end,audience=p_body->>'audience',status=p_body->>'status',photo_keys=coalesce(p_body->'photos','[]'),exchange_preference=coalesce(p_body->>'exchangePreference','') where exchange_listings.id=target and user_id=uid and project_id=pid;if not found then raise exception 'Own listing required';end if;id:=target;end if;return jsonb_build_object('id',id);end if;
 if p_route='social-reports' and p_method='POST' then target:=(p_body->>'targetId')::uuid;if p_body->>'kind' not in ('profile','post') or length(trim(p_body->>'reason')) not between 1 and 500 then raise exception 'Invalid report';end if;
 if p_body->>'kind'='profile' and not private.can_discover_profile(target) or p_body->>'kind'='post' and not private.post_is_visible(target) then raise exception 'Report target unavailable';end if;
 insert into private.social_reports(reporter_id,target_kind,target_id,reason) values(uid,p_body->>'kind',target,trim(p_body->>'reason'));return jsonb_build_object('ok',true);end if;
 raise exception 'Community endpoint unavailable';
end;$$;

create or replace function private.can_discover_profile(target uuid) returns boolean language sql stable security definer set search_path='' as $$select private.active_resident(auth.uid()) and private.active_resident(target) and not private.are_blocked(auth.uid(),target) and (auth.uid()=target or private.are_friends(auth.uid(),target) or exists(select 1 from public.social_profiles sp where sp.user_id=target and sp.discoverable and (sp.network_visible or exists(select 1 from public.projects p where private.project_member(auth.uid(),p.id) and private.project_member(target,p.id)))));$$;
drop policy eligible_rides on public.rides;
create policy eligible_rides on public.rides for select to authenticated using(private.active_resident(auth.uid()) and private.project_member(driver_id,project_id) and status='open' and departure>now() and not private.are_blocked(auth.uid(),driver_id));
drop policy own_ride_requests on public.ride_requests;
create policy own_ride_requests on public.ride_requests for select to authenticated using(private.active_resident(auth.uid()) and not private.are_blocked(auth.uid(),user_id) and exists(select 1 from public.rides r where r.id=ride_id and (user_id=auth.uid() or r.driver_id=auth.uid())));
commit;
